function sanitizeInput(req, res, next) {
  // Remove any non-printable characters from string inputs
  for (const [key, value] of Object.entries(req.query)) {
    if (typeof value === 'string') {
      req.query[key] = value.replace(/[^\x20-\x7E]/g, '');
    }
  }
  next();
}

