```javascript
// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { v4: uuidv4 } = require('uuid');

// Initialize app
const app = express();

// ============================================
// SECURITY: Security Headers
// ============================================
app.use(helmet());

// ============================================
// SECURITY: Rate Limiting (DoS protection)
// ============================================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', limiter);

// ============================================
// SECURITY: Request body parsing with limits
// ============================================
app.use(express.json({ 
  limit: '10kb', // Limit payload size to prevent DoS
  strict: true  // Only accept valid JSON
}));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ============================================
// SECURITY: Input Validation Helpers
// ============================================
const validatePositiveInteger = (value, fieldName) => {
  const parsed = parseInt(value, 10);
  if (isNaN(parsed) || parsed <= 0 || !Number.isInteger(parsed)) {
    throw new Error(`Invalid ${fieldName}: must be a positive integer`);
  }
  return parsed;
};

const sanitizeString = (value, maxLength = 255) => {
  if (typeof value !== 'string') return '';
  // Remove null bytes and control characters
  return value.replace(/[\x00-\x1F\x7F]/g, '').slice(0, maxLength);
};

// ============================================
// HEALTH ENDPOINT
// ============================================
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

// ============================================
// USERS ENDPOINT (with validation)
// ============================================
app.get('/users', (req, res, next) => {
  try {
    // Example: Validate query parameters if needed
    const { limit, offset } = req.query;

    let parsedLimit = 100; // Default
    let parsedOffset = 0;

    if (limit !== undefined) {
      parsedLimit = validatePositiveInteger(limit, 'limit');
      if (parsedLimit > 100) parsedLimit = 100; // Cap at 100
    }

    if (offset !== undefined) {
      parsedOffset = validatePositiveInteger(offset, 'offset');
    }

    // Simulated user data (in real app, this would be from a DB)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Validate output doesn't contain sensitive fields
    const safeUsers = users.map(user => ({
      id: user.id,
      name: sanitizeString(user.name),
      email: sanitizeString(user.email)
    }));

    // Return paginated response
    res.json({
      data: safeUsers.slice(parsedOffset, parsedOffset + parsedLimit),
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: safeUsers.length
      }
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// ============================================
// SECURITY: Global Error Handler
// ============================================
app.use((err, req, res, next) => {
  // Log error for security monitoring
  console.error(`[ERROR] ${new Date().toISOString()} - ${err.message}`, {
    path: req.path,
    method: req.method,
    ip: req.ip,
    stack: err.stack
  });

  // Don't expose internal error details to clients
  const statusCode = err.statusCode || err.status || 500;
  const message = statusCode === 500 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    requestId: req.id || uuidv4() // Help identify the request in logs
  });
});

// ============================================
// SECURITY: 404 Handler
// ============================================
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    requestId: req.id 
  });
});

// ============================================
// Start Server
// ============================================
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

